import sys
from collections import deque

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    k = int(data[2])

    grid = []
    idx = 3
    for i in range(n):
        grid.append(data[idx])
        idx += 1

    start_pos = None
    end_pos = None

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'S':
                start_pos = (r, c)
            elif grid[r][c] == 'T':
                end_pos = (r, c)

    if start_pos is None or end_pos is None:
        print("-1")
        return

    rows, cols = n, m
    directions = [(-1, 0), (0, -1), (0, 1), (1, 0)]
    dir_chars = ['U', 'L', 'R', 'D']

    best_path = None
    best_len = float('inf')

    queue = deque()
    queue.append((start_pos[0], start_pos[1], frozenset(), ""))

    while queue:
        r, c, types_used, path = queue.popleft()

        if (r, c) == end_pos:
            if len(path) < best_len:
                best_len = len(path)
                best_path = path
            elif len(path) == best_len and path < best_path:
                best_path = path
            continue

        if len(path) >= best_len:
            continue

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                cell = grid[nr][nc]
                if cell == 'S' or cell == 'T':
                    continue

                new_types = types_used | {cell}
                if len(new_types) <= k:
                    new_path = path + cell
                    if len(new_path) < best_len:
                        queue.append((nr, nc, new_types, new_path))
                    elif len(new_path) == best_len and best_path is not None and new_path < best_path:
                        queue.append((nr, nc, new_types, new_path])

    if best_path is None:
        print("-1")
    else:
        print(best_path)

if __name__ == "__main__":
    solve()
